mrb_value mrb_clone(mrb_state *mrb, mrb_value self) {
  mrb_value obj;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }

  if (mrb_singleton_class_p(mrb, self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  obj = mrb_obj_dup(mrb, self);
  mrb_obj_iv_copy(mrb, mrb_obj_value(mrb_obj_ptr(obj)), mrb_obj_value(mrb_obj_ptr(self)));

  if (mrb_obj_frozen(mrb_obj_ptr(self))) {
    mrb_obj_freeze(mrb, obj);
  }

  return obj;
}
